var TO_ADDRESS="bimalindelhi@gmail.com";function formatMailBody(c,d){var e="";if(!d){d=Object.keys(c)}for(var a in d){var b=d[a];e+="<h4 style='text-transform: capitalize; margin-bottom: 0'>"+b+"</h4><div>"+sanitizeInput(c[b])+"</div>"}return e}function sanitizeInput(b){var a=HtmlService.createHtmlOutput(" ");a.appendUntrusted(b);return a.getContent()}function doPost(b){try{Logger.log(b);record_data(b);var d=b.parameters;var f=b.parameters.formDataNameOrder;var a;if(f){a=JSON.parse(f)}var g=(typeof TO_ADDRESS!=="undefined")?TO_ADDRESS:d.formGoogleSendEmail;if(g){MailApp.sendEmail({to:String(g),subject:"Contact form submitted",htmlBody:formatMailBody(d,a)})}return ContentService.createTextOutput(JSON.stringify({result:"success",data:JSON.stringify(b.parameters)})).setMimeType(ContentService.MimeType.JSON)}catch(c){Logger.log(c);return ContentService.createTextOutput(JSON.stringify({result:"error",error:c})).setMimeType(ContentService.MimeType.JSON)}}function record_data(b){var j=LockService.getDocumentLock();j.waitLock(30000);try{Logger.log(JSON.stringify(b));var a=SpreadsheetApp.getActiveSpreadsheet();var q=b.parameters.formGoogleSheetName||"responses";var p=a.getSheetByName(q);var m=p.getRange(1,1,1,p.getLastColumn()).getValues()[0];var k=m.slice();var f=getDataColumns(b.parameters);var o=[new Date()];for(var h=1;h<m.length;h++){var d=m[h];var n=getFieldFromData(d,b.parameters);o.push(n);var g=f.indexOf(d);if(g>-1){f.splice(g,1)}}for(var h=0;h<f.length;h++){var d=f[h];var n=getFieldFromData(d,b.parameters);o.push(n);k.push(d)}var l=p.getLastRow()+1;p.getRange(l,1,1,o.length).setValues([o]);if(k.length>m.length){p.getRange(1,1,1,k.length).setValues([k])}}catch(c){Logger.log(c)}finally{j.releaseLock();return}}function getDataColumns(a){return Object.keys(a).filter(function(b){return !(b==="formDataNameOrder"||b==="formGoogleSheetName"||b==="formGoogleSendEmail"||b==="honeypot")})}function getFieldFromData(b,a){var d=a[b]||"";var c=d.join?d.join(", "):d;return c};